	final static int INF = (int) 1e9;

	Integer [] A;
	int N; int [] Q; int [][] R;

	public D () {
		N = sc.nextInt();
		A = sc.nextInts();

		if (N == 1)
			exit(1);

		next: for (int i : rep(1, N)) {
			for (int j : rep(i)) 
				for (int k : rep(i))
					if (A[j] + A[k] == A[i])
						continue next;
			exit(-1);
		}

		Map<Integer, Integer> M = new TreeMap<Integer, Integer>();
		for (int i : rep(N))
			M.put(A[i], i);

		Q = new int [N];
		R = new int [N][N];

		for (int i : rep(N))
			for (int j : rep(i))
				if (M.containsKey(A[i] - A[j])) {
					int k = M.get(A[i] - A[j]);
					Q[i] |= (1 << j);
					R[i][j] = k;
				}

		H = new int [1 << (N-1)]; fill(H, -1);

		int res = solve(1, 1);
		assert res <= N;
		exit(res);
	}

	int [] H;

	int solve(int X, int J) {
		int B = (X & Q[J]);
		if (B == 0)
			return H[X] = INF;

		for (int i = 0; i < J; ++i) {
			int U = (1 << i), V = (1 << R[J][i]);
			if ((B&U) != 0 && (B&V) != 0)
				break;
			if (i == J-1)
				return H[X] = INF;
		}

		if (J == N-1)
			return H[X] = Integer.bitCount(X);

		int Y = (X | (1 << J)), res = INF;
		for (int j = 0; j < J; ++j) {
			int W = (1 << j);
			if ((Y & W) != 0) {
				int V = Y & (~W), R = H[V] == -1 ? solve(V, J+1) : H[V];
				res = min(res, R);
			}
		}
		int R = H[Y] == -1 ? solve(Y, J+1) : H[Y];
		res = min(res, R);
		return H[X] = res;		
